SELECT s.s_acctbal,s.s_name,n.n_name,p.p_partkey,p.p_mfgr,s.s_address,s.s_phone,s.s_comment FROM tpch_part p JOIN tpch_partsupp ps ON p.p_partkey=ps.ps_partkey JOIN tpch_supplier s ON s.s_suppkey=ps.ps_suppkey JOIN tpch_nation n ON s.s_nationkey=n.n_nationkey JOIN tpch_region r ON n.n_regionkey=r.r_regionkey JOIN (SELECT ps0.ps_partkey,MIN(ps0.ps_supplycost) AS min_cost FROM tpch_partsupp ps0 JOIN tpch_supplier s0 ON s0.s_suppkey=ps0.ps_suppkey JOIN tpch_nation n0 ON s0.s_nationkey=n0.n_nationkey JOIN tpch_region r0 ON n0.n_regionkey=r0.r_regionkey WHERE r0.r_name='EUROPE' GROUP BY ps0.ps_partkey) mc ON mc.ps_partkey=ps.ps_partkey AND mc.min_cost=ps.ps_supplycost WHERE p.p_size=15 AND p.p_type LIKE '%BRASS' AND r.r_name='EUROPE' ORDER BY s.s_acctbal DESC,n.n_name,s.s_name,p.p_partkey LIMIT 100;
